import PyPDF2
with open('magnetar_bursts.pdf', 'rb') as file:
    reader = PyPDF2.PdfReader(file)
    text = ''
    for page in reader.pages:
        text += page.extract_text()

    print('=== Searching for exact burst width values ===')
    # Look for the specific 866 μs measurement
    lines = text.split('\n')
    for i, line in enumerate(lines):
        if '866' in line:
            # Check if it's related to burst width
            context_lines = lines[max(0, i-3):i+4]
            context_text = ' '.join(context_lines)
            if 'B1' in context_text and ('μs' in context_text or 'width' in context_text.lower()):
                print('--- BURST WIDTH CONTEXT ---')
                for j, cline in enumerate(context_lines):
                    if j == 3:  # Highlight the line with 866
                        print(f'>>> {cline} <<<')
                    else:
                        print(f'    {cline}')
                print('--- END ---')
                break

    print('\n=== Looking for scattering time measurements ===')
    # Look for scattering time measurements
    for i, line in enumerate(lines):
        if 'scattering' in line.lower() and 'time' in line.lower():
            if 'B1' in line or 'B2' in line or '315' in line or '299' in line:
                print('--- SCATTERING TIME CONTEXT ---')
                context = lines[max(0, i-1):i+2]
                for c in context:
                    print(c)
                print('--- END ---')
                break
